def countNearAnagrams(s, p, k):
    n, m = len(s), len(p)
    need = [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    have = [0] * 26
    matched = 0
    ans = 0
    for i in range(n):
        c = ord(s[i]) - 97
        if have[c] < need[c]:
            matched += 1
        have[c] += 1
        if i >= m:
            d = ord(s[i - m]) - 97
            have[d] -= 1
            if have[d] < need[d]:
                matched -= 1
        if i >= m - 1 and m - matched <= k:
            ans += 1
    return ans
